import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int K, int stride, int padding, int dilation, int groups,
    int Hout, int Wout,
    int IC_per_group, int OC_per_group)
{
  constexpr int TH = 8;
  constexpr int TW = 32;
  constexpr int RW = 2;                  // register blocking factor along output width
  constexpr int OC_PER_BLOCK = 32;
  constexpr int IC_CHUNK = 8;
  constexpr int TW_TOTAL = TW * RW;      // effective output tile width covered by a block
  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * blockDim.x + tx;
  const int nThreads = blockDim.x * blockDim.y;
  const int numOcBlocksPerGroup = (OC_per_group + OC_PER_BLOCK - 1) / OC_PER_BLOCK;
  const int totalOcBlocks = groups * numOcBlocksPerGroup;
  const int n   = blockIdx.z / totalOcBlocks;
  const int rem = blockIdx.z % totalOcBlocks;
  const int g   = rem / numOcBlocksPerGroup;
  const int oc_block = rem % numOcBlocksPerGroup;
  const int oc_base_in_group = oc_block * OC_PER_BLOCK;
  const int oc_base_global   = g * OC_per_group + oc_base_in_group;
  const int ic_base_global   = g * IC_per_group;
  const int oh0 = blockIdx.y * TH;
  const int ow0 = blockIdx.x * TW_TOTAL;
  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;
  const int TileH_halo = (TH - 1) * stride + (K - 1) * dilation + 1;
  const int TileW_halo = (TW_TOTAL - 1) * stride + (K - 1) * dilation + 1;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, IC_per_group, K, K),
      make_stride((int64_t)IC_per_group * K * K, (int64_t)K * K, K, Int<1>{})
  );
  extern __shared__ unsigned char smem_raw[];
  const int sIn_chunk_elems = IC_CHUNK * TileH_halo * TileW_halo;
  const int sW_chunk_elems  = OC_PER_BLOCK * IC_CHUNK * K * K;
  T* sIn_ptr0 = reinterpret_cast<T*>(smem_raw);
  T* sIn_ptr1 = sIn_ptr0 + sIn_chunk_elems;
  T* sW_ptr0  = sIn_ptr1 + sIn_chunk_elems;
  T* sW_ptr1  = sW_ptr0 + sW_chunk_elems;
  T* sIn_bufs[2] = { sIn_ptr0, sIn_ptr1 };
  T* sW_bufs[2]  = { sW_ptr0, sW_ptr1 };
  const int oh = oh0 + ty;
  const bool valid_row = (oh < Hout);
  float acc_reg[RW][OC_PER_BLOCK];
  #pragma unroll
  for (int r = 0; r < RW; ++r) {
    #pragma unroll
    for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
      int oc_local = oc_base_in_group + occ;
      float bval = 0.0f;
      if (B != nullptr && oc_local < OC_per_group) {
        int oc_global = g * OC_per_group + oc_local;
        bval = (float)B[oc_global];
      }
      acc_reg[r][occ] = bval;
    }
  }
#define LOAD_CONV_CHUNK(SIN_PTR, SW_PTR, IC_START, CH_SIZE)                             \
  do {                                                                                   \
    auto sIn_b = make_tensor(                                                            \
        make_smem_ptr(SIN_PTR),                                                          \
        make_shape(IC_CHUNK, TileH_halo, TileW_halo),                                    \
        make_stride(TileH_halo * TileW_halo, TileW_halo, Int<1>{})                       \
    );                                                                                   \
    auto sW_b = make_tensor(                                                             \
        make_smem_ptr(SW_PTR),                                                          \
        make_shape(OC_PER_BLOCK, IC_CHUNK, K, K),                                        \
        make_stride(IC_CHUNK * K * K, K * K, K, Int<1>{})                                \
    );                                                                                   \
    int total_elems_ = (CH_SIZE) * TileH_halo * TileW_halo;                              \
    for (int idx = tid; idx < total_elems_; idx += nThreads) {                           \
      int icc = idx / (TileH_halo * TileW_halo);                                         \
      int rem2 = idx % (TileH_halo * TileW_halo);                                        \
      int hh = rem2 / TileW_halo;                                                        \
      int ww = rem2 % TileW_halo;                                                        \
      int ic_global = ic_base_global + (IC_START) + icc;                                 \
      int ih = ih0 + hh;                                                                 \
      int iw = iw0 + ww;                                                                 \
      T val = T(0);                                                                      \
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {                                     \
        val = mX(ic_global, ih, iw);                                                     \
      }                                                                                   \
      sIn_b(icc, hh, ww) = val;                                                          \
    }                                                                                     \
    int total_w_ = OC_PER_BLOCK * (CH_SIZE) * K * K;                                     \
    for (int idx = tid; idx < total_w_; idx += nThreads) {                               \
      int occ = idx / ((CH_SIZE) * K * K);                                               \
      int r = idx % ((CH_SIZE) * K * K);                                                 \
      int icc = r / (K * K);                                                             \
      int r2 = r % (K * K);                                                              \
      int kh = r2 / K;                                                                    \
      int kw = r2 % K;                                                                    \
      int oc_local = oc_base_in_group + occ;                                              \
      T val = T(0);                                                                       \
      if (oc_local < OC_per_group) {                                                       \
        int oc_global = g * OC_per_group + oc_local;                                       \
        int ic_local = (IC_START) + icc;                                                   \
        val = mW(oc_global, ic_local, kh, kw);                                             \
      }                                                                                    \
      sW_b(occ, icc, kh, kw) = val;                                                        \
    }                                                                                      \
  } while (0)
  int first_chunk_size = IC_per_group < IC_CHUNK ? IC_per_group : IC_CHUNK;
  LOAD_CONV_CHUNK(sIn_bufs[0], sW_bufs[0], 0, first_chunk_size);
  __syncthreads();
  int cur_buf = 0;
  for (int ic_chunk_start = 0; ic_chunk_start < IC_per_group; ic_chunk_start += IC_CHUNK) {
    int chunk_size = IC_per_group - ic_chunk_start;
    if (chunk_size > IC_CHUNK) chunk_size = IC_CHUNK;
    int next_start = ic_chunk_start + IC_CHUNK;
    int next_buf = cur_buf ^ 1;
    if (next_start < IC_per_group) {
      int next_chunk_size = IC_per_group - next_start;
      if (next_chunk_size > IC_CHUNK) next_chunk_size = IC_CHUNK;
      LOAD_CONV_CHUNK(sIn_bufs[next_buf], sW_bufs[next_buf], next_start, next_chunk_size);
    }
    auto sIn_cur = make_tensor(
        make_smem_ptr(sIn_bufs[cur_buf]),
        make_shape(IC_CHUNK, TileH_halo, TileW_halo),
        make_stride(TileH_halo * TileW_halo, TileW_halo, Int<1>{})
    );
    auto sW_cur = make_tensor(
        make_smem_ptr(sW_bufs[cur_buf]),
        make_shape(OC_PER_BLOCK, IC_CHUNK, K, K),
        make_stride(IC_CHUNK * K * K, K * K, K, Int<1>{})
    );
    if (valid_row) {
      for (int icc = 0; icc < chunk_size; ++icc) {
        for (int kh = 0; kh < K; ++kh) {
          int hh = ty * stride + kh * dilation;
          for (int kw = 0; kw < K; ++kw) {
            float xval[RW];
            #pragma unroll
            for (int r = 0; r < RW; ++r) {
              int ww = (tx + r * TW) * stride + kw * dilation;
              xval[r] = (float)sIn_cur(icc, hh, ww);
            }
            #pragma unroll
            for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
              int oc_local = oc_base_in_group + occ;
              if (oc_local >= OC_per_group) continue;
              float wval = (float)sW_cur(occ, icc, kh, kw);
              #pragma unroll
              for (int r = 0; r < RW; ++r) {
                acc_reg[r][occ] += xval[r] * wval;
              }
            }
          }
        }
      }
    }
    __syncthreads();
    cur_buf = next_buf;
  }
#undef LOAD_CONV_CHUNK
  if (valid_row) {
    #pragma unroll
    for (int r = 0; r < RW; ++r) {
      int ow = ow0 + tx + r * TW;
      if (ow >= Wout) continue;
      #pragma unroll
      for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
        int oc_local = oc_base_in_group + occ;
        if (oc_local >= OC_per_group) continue;
        int oc_global = g * OC_per_group + oc_local;
        mY(oc_global, oh, ow) = static_cast<T>(acc_reg[r][occ]);
      }
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, IC/groups, K, K]");

  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t OC = w.size(0);
  int64_t IC_per_group = w.size(1);
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square");
  TORCH_CHECK(C == IC_per_group * groups, "in_channels mismatch with groups");
  TORCH_CHECK(OC % groups == 0, "out_channels must be divisible by groups");
  int64_t OC_per_group = OC / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int TH = 8;
  constexpr int TW = 32;
  constexpr int RW = 2;
  constexpr int OC_PER_BLOCK = 32;
  constexpr int IC_CHUNK = 8;
  constexpr int TW_TOTAL = TW * RW;
  int TileH_halo = (TH - 1) * stride + (int)(K - 1) * dilation + 1;
  int TileW_halo = (TW_TOTAL - 1) * stride + (int)(K - 1) * dilation + 1;
  size_t smem_bytes = (size_t)2 * (IC_CHUNK * TileH_halo * TileW_halo +
                                OC_PER_BLOCK * IC_CHUNK * K * K) * sizeof(float);
  int numOcBlocksPerGroup = (int)((OC_per_group + OC_PER_BLOCK - 1) / OC_PER_BLOCK);
  int totalOcBlocks = groups * numOcBlocksPerGroup;
  dim3 block(TW, TH);
  dim3 grid(
      (unsigned)((Wout + TW_TOTAL - 1) / TW_TOTAL),
      (unsigned)((Hout + TH - 1) / TH),
      (unsigned)(N * totalOcBlocks)
  );
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)K, stride, padding, dilation, groups,
      (int)Hout, (int)Wout,
      (int)IC_per_group, (int)OC_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a custom CUDA kernel using CuTe tensors
    for tiled shared-memory cooperative computation.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        IC_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, IC_per_group, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

