import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int K, int stride, int padding, int dilation, int groups,
    int Hout, int Wout,
    int IC_per_group, int OC_per_group)
{
  constexpr int TH = 8;
  constexpr int TW = 32;
  constexpr int OC_PER_BLOCK = 32;
  constexpr int IC_CHUNK = 8;

  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * blockDim.x + tx;
  const int nThreads = blockDim.x * blockDim.y;

  const int numOcBlocksPerGroup = (OC_per_group + OC_PER_BLOCK - 1) / OC_PER_BLOCK;
  const int totalOcBlocks = groups * numOcBlocksPerGroup;

  const int n   = blockIdx.z / totalOcBlocks;
  const int rem = blockIdx.z % totalOcBlocks;
  const int g   = rem / numOcBlocksPerGroup;
  const int oc_block = rem % numOcBlocksPerGroup;

  const int oc_base_in_group = oc_block * OC_PER_BLOCK;
  const int oc_base_global   = g * OC_per_group + oc_base_in_group;
  const int ic_base_global   = g * IC_per_group;

  const int oh0 = blockIdx.y * TH;
  const int ow0 = blockIdx.x * TW;

  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;

  const int TileH_halo = (TH - 1) * stride + (K - 1) * dilation + 1;
  const int TileW_halo = (TW - 1) * stride + (K - 1) * dilation + 1;

  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, IC_per_group, K, K),
      make_stride((int64_t)IC_per_group * K * K, (int64_t)K * K, K, Int<1>{})
  );

  extern __shared__ unsigned char smem_raw[];
  const int sIn_chunk_elems = IC_CHUNK * TileH_halo * TileW_halo;
  const int sW_chunk_elems  = OC_PER_BLOCK * IC_CHUNK * K * K;
  T* sIn_ptr0 = reinterpret_cast<T*>(smem_raw);
  T* sIn_ptr1 = sIn_ptr0 + sIn_chunk_elems;
  T* sW_ptr0  = sIn_ptr1 + sIn_chunk_elems;
  T* sW_ptr1  = sW_ptr0 + sW_chunk_elems;
  T* sIn_bufs[2] = { sIn_ptr0, sIn_ptr1 };
  T* sW_bufs[2]  = { sW_ptr0, sW_ptr1 };
  const int oh = oh0 + ty;
  const int ow = ow0 + tx;
  const bool valid_pix = (oh < Hout && ow < Wout);
  float acc_reg[OC_PER_BLOCK];
  #pragma unroll
  for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
    int oc_local = oc_base_in_group + occ;
    float bval = 0.0f;
    if (B != nullptr && oc_local < OC_per_group) {
      int oc_global = g * OC_per_group + oc_local;
      bval = (float)B[oc_global];
    }
    acc_reg[occ] = bval;
  }
#define LOAD_CONV_CHUNK(SIN_PTR, SW_PTR, IC_START, CH_SIZE)                             \
  do {                                                                                   \
    auto sIn_b = make_tensor(                                                            \
        make_smem_ptr(SIN_PTR),                                                          \
        make_shape(IC_CHUNK, TileH_halo, TileW_halo),                                    \
        make_stride(TileH_halo * TileW_halo, TileW_halo, Int<1>{})                       \
    );                                                                                   \
    auto sW_b = make_tensor(                                                             \
        make_smem_ptr(SW_PTR),                                                           \
        make_shape(OC_PER_BLOCK, IC_CHUNK, K, K),                                        \
        make_stride(IC_CHUNK * K * K, K * K, K, Int<1>{})                                \
    );                                                                                   \
    int total_elems_ = (CH_SIZE) * TileH_halo * TileW_halo;                              \
    for (int idx = tid; idx < total_elems_; idx += nThreads) {                           \
      int icc = idx / (TileH_halo * TileW_halo);                                         \
      int rem2 = idx % (TileH_halo * TileW_halo);                                        \
      int hh = rem2 / TileW_halo;                                                        \
      int ww = rem2 % TileW_halo;                                                        \
      int ic_global = ic_base_global + (IC_START) + icc;                                 \
      int ih = ih0 + hh;                                                                 \
      int iw = iw0 + ww;                                                                 \
      T val = T(0);                                                                      \
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {                                     \
        val = mX(ic_global, ih, iw);                                                     \
      }                                                                                   \
      sIn_b(icc, hh, ww) = val;                                                          \
    }                                                                                     \
    int total_w_ = OC_PER_BLOCK * (CH_SIZE) * K * K;                                     \
    for (int idx = tid; idx < total_w_; idx += nThreads) {                               \
      int occ = idx / ((CH_SIZE) * K * K);                                               \
      int r = idx % ((CH_SIZE) * K * K);                                                 \
      int icc = r / (K * K);                                                             \
      int r2 = r % (K * K);                                                              \
      int kh = r2 / K;                                                                    \
      int kw = r2 % K;                                                                    \
      int oc_local = oc_base_in_group + occ;                                              \
      T val = T(0);                                                                       \
      if (oc_local < OC_per_group) {                                                       \
        int oc_global = g * OC_per_group + oc_local;                                       \
        int ic_local = (IC_START) + icc;                                                   \
        val = mW(oc_global, ic_local, kh, kw);                                             \
