  }

  for (int ic_chunk_start = 0; ic_chunk_start < IC_per_group; ic_chunk_start += IC_CHUNK) {
    int chunk_size = IC_per_group - ic_chunk_start;
    if (chunk_size > IC_CHUNK) chunk_size = IC_CHUNK;

    int total_elems = chunk_size * TileH_halo * TileW_halo;
    for (int idx = tid; idx < total_elems; idx += nThreads) {
      int icc = idx / (TileH_halo * TileW_halo);
      int rem2 = idx % (TileH_halo * TileW_halo);
      int hh = rem2 / TileW_halo;
      int ww = rem2 % TileW_halo;

      int ic_global = ic_base_global + ic_chunk_start + icc;
      int ih = ih0 + hh;
      int iw = iw0 + ww;

      T val = T(0);
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        val = mX(ic_global, ih, iw);
      }
      sIn(icc, hh, ww) = val;
    }

    int total_w = OC_PER_BLOCK * chunk_size * K * K;
    for (int idx = tid; idx < total_w; idx += nThreads) {
      int occ = idx / (chunk_size * K * K);
      int r = idx % (chunk_size * K * K);
      int icc = r / (K * K);
      int r2 = r % (K * K);
      int kh = r2 / K;
      int kw = r2 % K;

      int oc_local = oc_base_in_group + occ;
      T val = T(0);
      if (oc_local < OC_per_group) {
        int oc_global = g * OC_per_group + oc_local;
        int ic_local = ic_chunk_start + icc;
        val = mW(oc_global, ic_local, kh, kw);
      }
      sW(occ, icc, kh, kw) = val;
    }

    __syncthreads();

    if (valid_pix) {
      for (int icc = 0; icc < chunk_size; ++icc) {
        for (int kh = 0; kh < K; ++kh) {
          int hh = ty * stride + kh * dilation;
          for (int kw = 0; kw < K; ++kw) {
            int ww = tx * stride + kw * dilation;
            float xval = (float)sIn(icc, hh, ww);
            #pragma unroll
            for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
              int oc_local = oc_base_in_group + occ;
              if (oc_local >= OC_per_group) continue;
              float wval = (float)sW(occ, icc, kh, kw);
              acc_reg[occ] += xval * wval;
            }
          }
        }
      }
    }

    __syncthreads();
  }

  if (valid_pix) {
    #pragma unroll
    for (int occ = 0; occ < OC_PER_BLOCK; ++occ) {
      int oc_local = oc_base_in_group + occ;
      if (oc_local >= OC_per_group) continue;
      int oc_global = g * OC_per_group + oc_local;
      mY(oc_global, oh, ow) = static_cast<T>(acc_reg[occ]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, IC/groups, K, K]");

  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t OC = w.size(0);
  int64_t IC_per_group = w.size(1);
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square");
  TORCH_CHECK(C == IC_per_group * groups, "in_channels mismatch with groups");
  TORCH_CHECK(OC % groups == 0, "out_channels must be divisible by groups");
  int64_t OC_per_group = OC / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int TH = 8;
  constexpr int TW = 32;
  constexpr int OC_PER_BLOCK = 32;
  constexpr int IC_CHUNK = 8;

  int TileH_halo = (TH - 1) * stride + (int)(K - 1) * dilation + 1;
  int TileW_halo = (TW - 1) * stride + (int)(K - 1) * dilation + 1;

  size_t smem_bytes = (size_t)(IC_CHUNK * TileH_halo * TileW_halo +
                                OC_PER_BLOCK * IC_CHUNK * K * K) * sizeof(float);

  int numOcBlocksPerGroup = (int)((OC_per_group + OC_PER_BLOCK - 1) / OC_PER_BLOCK);
  int totalOcBlocks = groups * numOcBlocksPerGroup;

  dim3 block(TW, TH);
  dim3 grid(
      (unsigned)((Wout + TW - 1) / TW),
      (unsigned)((Hout + TH - 1) / TH),
      (unsigned)(N * totalOcBlocks)
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)K, stride, padding, dilation, groups,
      (int)Hout, (int)Wout,
      (int)IC_per_group, (int)OC_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
